private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Ensure the buffer has enough remaining bytes to decode a character.
    int remaining = bb.remaining();
    // Position within the buffer is relative to its start.
    int bufferPos = bb.position();
    int index = bufferPos + i;
    if (index >= bb.limit()) {
        // No bytes left to decode; return the current index.
        return i;
    }
    int b0 = bb.get(index) & 0xFF;
    // 1-byte (ASCII)
    if ((b0 & 0x80) == 0) {
        sb.append((char) b0);
        return i + 1;
    }
    // Determine the number of bytes for this UTF‑8 sequence
    int expectedLength = 0;
    int codePoint = 0;
    if ((b0 & 0xE0) == 0xC0) {
        expectedLength = 2;
        codePoint = b0 & 0x1F;
    } else if ((b0 & 0xF0) == 0xE0) {
        expectedLength = 3;
        codePoint = b0 & 0x0F;
    } else if ((b0 & 0xF8) == 0xF0) {
        expectedLength = 4;
        codePoint = b0 & 0x07;
    } else {
        // Invalid UTF‑8 start byte; append replacement char.
        sb.append('\uFFFD');
        return i + 1;
    }
    // Verify that the buffer contains the required number of bytes.
    if (i + expectedLength > bb.limit() - bufferPos) {
        // Incomplete sequence; append replacement and return finished index.
        sb.append('\uFFFD');
        return i + (bb.limit() - bufferPos - i);
    }
    // Decode continuation bytes
    for (int j = 1; j < expectedLength; j++) {
        int b = bb.get(index + j) & 0xFF;
        if ((b & 0xC0) != 0x80) {
            // Invalid continuation byte; append replacement and adjust index.
            sb.append('\uFFFD');
            return i + j;
        }
        codePoint = (codePoint << 6) | (b & 0x3F);
    }
    // Append the decoded code point.
    if (expectedLength == 4) {
        // Encode as surrogate pair
        codePoint -= 0x10000;
        sb.append((char) ((codePoint >> 10) + 0xD800));
        sb.append((char) ((codePoint & 0x3FF) + 0xDC00));
    } else {
        sb.append((char) codePoint);
    }
    return i + expectedLength;
}

