public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    try {
        if (!(genericType instanceof ParameterizedType)) {
            return null;
        }
        ParameterizedType ptype = (ParameterizedType) genericType;
        Type[] typeArgs = ptype.getActualTypeArguments();
        Class<?>[] result = new Class<?>[typeArgs.length];
        Map<TypeVariable<?>, Type> typeVarMap = buildTypeVariableMap(targetType);
        for (int i = 0; i < typeArgs.length; i++) {
            Class<?> cls = resolveTypeArgument(typeArgs[i], typeVarMap);
            if (cls == null) {
                return null;
            }
            result[i] = cls;
        }
        return result;
    } catch (Throwable t) {
        // In case of any reflection or casting error, return null as spec indicates failure
        return null;
    }
}

private static Class<?> resolveTypeArgument(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        Type raw = ((ParameterizedType) type).getRawType();
        if (raw instanceof Class<?>) {
            return (Class<?>) raw;
        }
        return null;
    }
    if (type instanceof WildcardType) {
        WildcardType wt = (WildcardType) type;
        Type[] upper = wt.getUpperBounds();
        if (upper.length > 0) {
            return resolveTypeArgument(upper[0], map);
        }
        return null;
    }
    if (type instanceof TypeVariable<?>) {
        TypeVariable<?> tv = (TypeVariable<?>) type;
        Type mapped = map.get(tv);
        if (mapped != null && !mapped.equals(tv)) {
            return resolveTypeArgument(mapped, map);
        }
        return null;
    }
    return null;
}

private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Class<?> clazz) {
    Map<TypeVariable<?>, Type> map = new HashMap<>();
    try {
        // Handle superclass
        Type genericSup = clazz.getGenericSuperclass();
        if (genericSup instanceof ParameterizedType) {
            ParameterizedType sup = (ParameterizedType) genericSup;
            Class<?> rawSup = (Class<?>) sup.getRawType();
            TypeVariable<?>[] vars = rawSup.getTypeParameters();
            Type[] args = sup.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                map.put(vars[i], args[i]);
            }
        }
        // Handle interfaces (first match)
        for (Type iface : clazz.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType iPf = (ParameterizedType) iface;
                Class<?> rawIface = (Class<?>) iPf.getRawType();
                TypeVariable<?>[] vars = rawIface.getTypeParameters();
                Type[] args = iPf.getActualTypeArguments();
                for (int i = 0; i < vars.length; i++) {
                    map.put(vars[i], args[i]);
                }
                // Break after first to avoid redundancy
                break;
            }
        }
    } catch (Throwable ignored) {
        // Return whatever we could build
    }
    return map;
}

