public boolean equals(final byte[] data,int offset,final int len){
    // Validate the input parameters
    if (data == null) {
        return false;
    }
    if (offset < 0 || len < 0 || offset + len > data.length) {
        return false;
    }

    // If the internal array is null, only match an empty slice
    if (this.bytes == null) {
        return len == 0;
    }

    // Lengths must be identical
    if (this.bytes.length != len) {
        return false;
    }

    // Element‑wise comparison
    for (int i = 0; i < len; i++) {
        if (this.bytes[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

