protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be a positive value");
    }
    if (start > end) {
        throw new IllegalArgumentException("start (" + start + ") must not be greater than end (" + end + ")");
    }
    if (start == end) {
        return new ArrayList<>(0);
    }

    List<TimeRange> ranges = new ArrayList<>();
    long step = FETCH_DATA_DURATION;
    for (long current = start; current < end; ) {
        long next;
        if (current > Long.MAX_VALUE - step) {
            next = end;
        } else {
            next = Math.min(end, current + step);
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

