static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if(timeBucket <= 0){
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket % 10000) / 100);
    int day = (int)(timeBucket % 100);
    if(month < 1 || month > 12){
        throw new IllegalArgumentException("month out of range: " + month);
    }
    if(day < 1 || day > 31){
        throw new IllegalArgumentException("day out of range: " + day);
    }
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

int function ( @ Nullable final CharSequence arg0, final int arg1, final int arg2 ) {
    if (arg0 == null) {
        return 0;
    }
    if (arg1 < 0 || arg2 < 0) {
        return 0;
    }
    int stringLen = arg0.length();
    if (arg1 > stringLen) {
        return 0;
    }
    int end = arg1 + arg2;
    if (end > stringLen) {
        end = stringLen;
    }
    int size = 0;
    int i = arg1;
    while (i < end) {
        char c = arg0.charAt(i);
        int cp;
        if (Character.isHighSurrogate(c) && (i + 1) < end) {
            char low = arg0.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                cp = Character.toCodePoint(c, low);
                i++; // skip low surrogate
            } else {
                cp = c; // malformed pair; treat high surrogate as single char
            }
        } else if (Character.isLowSurrogate(c)) {
            cp = c; // malformed low surrogate alone
        } else {
            cp = c;
        }
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i++;
    }
    return size;
}

