public void removeFromTreeEdgeList(){
    // Remove from primary tree edge list
    if (prevTreeEdge != null) {
        prevTreeEdge.nextTreeEdge = nextTreeEdge;
    }
    if (nextTreeEdge != null) {
        nextTreeEdge.prevTreeEdge = prevTreeEdge;
    }
    // Remove from secondary tree edge list
    if (prevTreeParentEdge != null) {
        prevTreeParentEdge.nextTreeParentEdge = nextTreeParentEdge;
    }
    if (nextTreeParentEdge != null) {
        nextTreeParentEdge.prevTreeParentEdge = prevTreeParentEdge;
    }
    // Nullify this edge's references
    prevTreeEdge = null;
    nextTreeEdge = null;
    prevTreeParentEdge = null;
    nextTreeParentEdge = null;
}

