private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    String params = descriptor;
    if (descriptor.charAt(0) == '('){
        int start = descriptor.indexOf('(');
        int end = descriptor.indexOf(')');
        if (start < 0 || end < 0 || end <= start){
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        params = descriptor.substring(start + 1, end);
    }
    int i = 0;
    while (i < params.length()){
        char c = params.charAt(i);
        int slots = 0;
        int next = i + 1;
        if (c == 'L'){
            int semicolon = params.indexOf(';', i);
            if (semicolon < 0){
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            next = semicolon + 1;
            slots = 1;
        }else if (c == '['){
            while (params.charAt(next) == '['){
                next++;
            }
            char comp = params.charAt(next);
            if (comp == 'L'){
                int semicolon = params.indexOf(';', next);
                if (semicolon < 0){
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                next = semicolon + 1;
                slots = 1;
            }else if ("BCDFIJSZ".indexOf(comp) >= 0){
                slots = (comp == 'J' || comp == 'D') ? 2 : 1;
                next++;
            }else{
                throw new IllegalArgumentException("Invalid descriptor component: " + comp);
            }
        }else if ("BCDFIJSZ".indexOf(c) >= 0){
            slots = (c == 'J' || c == 'D') ? 2 : 1;
            next = i + 1;
        }else{
            throw new IllegalArgumentException("Unknown type descriptor: " + c);
        }
        for (int s = 0; s < slots; s++){
            if (pos <= 0){
                throw new IllegalStateException("Frame stack underflow when popping descriptor: " + descriptor);
            }
            pos--;
            stack[pos] = null;
        }
        i = next;
    }
}

/** 
 * Writes <code>len</code> bytes from the specified byte array starting at offset <code>off</code> to this byte array output stream.
 * @param b   the data.
 * @param off the start offset in the data.
 * @param len the number of bytes to write.
 */
@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("buffer is null");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException("offset: " + off + ", length: " + len + ", array length: " + b.length);
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        byte[] newBuf = new byte[Math.max(newCount, buf.length * 2)];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
        throw new IllegalArgumentException("Array is null");
    }
    int len = arr.length;
    if (i < 0 || i >= len || j < 0 || j >= len) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }
    if (i == j) {
        return;
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

