public String format(final LoggingEvent event){
    try{
        if(event == null){
            return "";
        }
        StringBuilder sb = new StringBuilder();
        // Format timestamp
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        sb.append(sdf.format(new java.util.Date(event.getTimeStamp())));
        sb.append('[').append(event.getThreadName()).append(']');
        sb.append(' ').append(event.getLevel()).append(' ');
        sb.append(event.getLoggerName()).append(": ");
        // Append message
        Object msgObj = event.getMessage();
        if(msgObj != null){
            sb.append(msgObj.toString());
        } else {
            sb.append("No message");
        }
        // Append throwable information if present
        if(event.getThrowableInformation() != null){
            String[] trace = event.getThrowableInformation().getThrowableStrRep();
            if(trace != null && trace.length > 0){
                sb.append(System.lineSeparator()).append(String.join(System.lineSeparator(), trace));
            } else {
                sb.append(System.lineSeparator()).append("Throwable information unavailable");
            }
        }
        return sb.toString();
    } catch(Exception e){
        return "Formatting error: " + e.getMessage();
    }
}

