@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!Character.class.isAssignableFrom(type) && type != char.class) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }
    if (value == null) {
        return null;
    }
    // If already a Character, just return it
    if (value instanceof Character) {
        return value;
    }
    // Handle CharSequence (e.g., String, StringBuilder)
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 0) {
            throw new Exception("Cannot convert an empty CharSequence to Character");
        }
        return cs.charAt(0);
    }
    // Handle numeric values by interpreting them as Unicode code points
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }
    // Fallback: use the string representation of the value
    String str = value.toString();
    if (str.isEmpty()) {
        throw new Exception("Cannot convert an empty string to Character");
    }
    return str.charAt(0);
}

