public static int nextPrime(int desiredCapacity){
    // Handle non-positive capacities
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // Make candidate odd if it is even and greater than 2
    if ((candidate & 1) == 0) {
        candidate++;
    }
    // Upper bound for searching 11% above desiredCapacity if large enough
    int upperBound = desiredCapacity >= 1000 ? (int)(desiredCapacity * 1.11f) : Integer.MAX_VALUE;
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Move to the next odd number
        candidate += 2;
        // If we pass the upper bound for the 11% rule, continue searching; 
        // the loop will eventually find a prime (prime numbers become dense).
        // To avoid overflow, stop when candidate reaches Integer.MAX_VALUE.
        if (candidate < 0) { // overflow check
            return Integer.MAX_VALUE;
        }
    }

    // Helper method to test primality
    // (defined as a static nested in the same class but separate method below)
}
private static boolean isPrime(int n) {
    if (n <= 3) {
        return n > 1;
    }
    if ((n & 1) == 0) {
        return false;
    }
    int limit = (int)Math.sqrt(n);
    for (int i = 3; i <= limit; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

