@Override
public String readString() throws IOException {
    // First read a 4‑byte big‑endian length prefix
    int length = 0;
    for (int i = 0; i < 4; i++) {
        int b = input.read();
        if (b == -1) {
            throw new EOFException("Unexpected end of stream while reading string length");
        }
        length = (length << 8) | (b & 0xFF);
    }
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    if (length == 0) {
        return "";
    }

    // Read the string bytes
    byte[] data = new byte[length];
    int offset = 0;
    while (offset < length) {
        int cnt = input.read(data, offset, length - offset);
        if (cnt == -1) {
            throw new EOFException("Unexpected end of stream while reading string");
        }
        offset += cnt;
    }

    // Convert to a UTF‑8 string (or change charset if needed)
    return new String(data, java.nio.charset.StandardCharsets.UTF_8);
}

private static int digitValue(final char c){
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    return -1;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> result = new LinkedHashMap<>();
    if(jsonObject == null){
        return result;
    }
    for(Map.Entry<String,JsonElement> entry : jsonObject.entrySet()){
        String key = entry.getKey();
        JsonElement elem = entry.getValue();
        Object value;
        if(elem == null || elem.isJsonNull()){
            value = null;
        } else if(elem.isJsonPrimitive()){
            JsonPrimitive prim = elem.getAsJsonPrimitive();
            if(prim.isBoolean()){
                value = prim.getAsBoolean();
            } else if(prim.isNumber()){
                value = prim.getAsNumber();
            } else {
                value = prim.getAsString();
            }
        } else if(elem.isJsonObject()){
            value = elem.getAsJsonObject();
        } else if(elem.isJsonArray()){
            value = elem.getAsJsonArray();
        } else {
            value = null;
        }
        result.put(key, value);
    }
    // If there is an "ats" key, flag that ATS was found
    if(result.containsKey("ats") && result.get("ats") != null){
        result.put("hasAts", true);
    }
    return result;
}

