public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                sb.append('\\');
                break;
            }
            char next = str.charAt(i + 1);
            if (next == '\\') { // escaped backslash
                sb.append('\\');
                i++; // skip the second backslash
            } else {
                switch (next) {
                    case 'b':
                        sb.append('\b');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case '\"':
                        sb.append('\"');
                        break;
                    case 'u': {
                        if (i + 6 > len) {
                            throw new IllegalArgumentException("Invalid unicode escape sequence at index " + i);
                        }
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid unicode escape sequence: \\u" + hex, e);
                        }
                        i += 5; // skip 'u' and 4 hex digits
                        break;
                    }
                    default:
                        sb.append(next);
                }
                i++; // skip the escaped character
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

