protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // Assume there is a field named 'root' representing the root of the Category tree
        if (root == null) {
            return 0;
        }
        Deque<Category> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            List<Category> children = current.getChildren();
            if (children == null || children.isEmpty()) {
                continue;
            }
            Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) { // 'isActive' determines if the node is still in use
                    it.remove();        // remove inactive child
                    removedCount++;
                } else {
                    stack.push(child);   // keep exploring active nodes
                }
            }
        }
    } catch (Exception e) {
        // If there is a logger available, one could log the exception here
        // For now we simply swallow it so the method always returns a count
    }
    return removedCount;
}

