private void check(String modelName) throws IllegalStateException {
    // Retrieve the sharding key indices for the given model.
    int[] indices = getShardingKeyIndices(modelName);

    // If no indices or only a single index, they are trivially continuous.
    if (indices == null || indices.length <= 1) {
        return;
    }

    // Verify that each subsequent index is exactly one greater than the previous.
    for (int i = 1; i < indices.length; i++) {
        if (indices[i] != indices[i - 1] + 1) {
            throw new IllegalStateException(
                "sharding key indices for " + modelName + " are not continuous");
        }
    }
}

