protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (graph == null){
        throw new IllegalArgumentException("graph is null");
    }
    if (tour == null || tour.isEmpty()){
        return new GraphWalk<>(graph, null, null, new ArrayList<>(), new ArrayList<>());
    }
    // Build adjacency lists for each vertex
    Map<V, Set<E>> adjacency = new HashMap<>();
    for (E e : tour){
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new HashSet<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new HashSet<>()).add(e);
    }
    // Find a starting vertex: prefer a vertex with degree 1 (path endpoint)
    V start = null;
    for (Map.Entry<V, Set<E>> entry : adjacency.entrySet()){
        if (entry.getValue().size() == 1){
            start = entry.getKey();
            break;
        }
    }
    if (start == null){
        // All vertices have degree 2 -> cycle, pick an arbitrary start
        start = graph.getEdgeSource(tour.iterator().next());
    }
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    V current = start;
    vertexList.add(current);
    while (!remaining.isEmpty()){
        E nextEdge = null;
        for (E e : adjacency.get(current)){
            if (remaining.contains(e)){
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null){
            break; // no further edges (should not happen in a proper tour)
        }
        remaining.remove(nextEdge);
        edgeList.add(nextEdge);
        V src = graph.getEdgeSource(nextEdge);
        V tgt = graph.getEdgeTarget(nextEdge);
        V nextVertex = current.equals(src) ? tgt : src;
        current = nextVertex;
        vertexList.add(current);
    }
    V target = vertexList.get(vertexList.size() - 1);
    return new GraphWalk<>(graph, start, target, vertexList, edgeList);
}

