        buffer.append(fieldName).append("=[");
    } else {
        buffer.append("[");
    }
    for (int i = 0; i < array.length; i++) {
        if (i > 0) {
            buffer.append(", ");
        }
        int value = array[i] & 0xFF; // unsigned value
        String hex = Integer.toHexString(value).toUpperCase();
        if (hex.length() == 1) {
            buffer.append('0');
        }
        buffer.append(hex);
    }
    buffer.append("]\n");
}

