private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        return false;
    }
    // Capture adjacent nodes before we modify links
    ListNodeImpl<E> prev = node.prev; // may be null if node is first
    ListNodeImpl<E> next = node.next; // may be null if node is last
    // Remove node from the list by re-linking its neighbours
    if (prev != null) {
        prev.next = next;
    } else {
        // node was the first element
        head = next;
    }
    if (next != null) {
        next.prev = prev;
    } else {
        // node was the last element
        tail = prev;
    }
    // Clear the removed node's references to avoid memory leaks
    node.prev = null;
    node.next = null;
    // Update size counter
    size--;
    return true;
}

