private String parseToken(final char[] terminators){
    if (terminators == null || terminators.length == 0) {
        return "";
    }
    int start = this.pos;
    while (this.pos < this.len) {
        char current = this.chars[this.pos];
        boolean isTerminator = false;
        for (char t : terminators) {
            if (current == t) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break;
        }
        this.pos++;
    }
    if (start >= this.pos) {
        return "";
    }
    return new String(this.chars, start, this.pos - start);
}

