private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds cannot be null");
    }
    int n = bounds.size();
    long running = 0;
    long[] suffixLong = new long[n];
    for (int i = n - 1; i >= 0; i--) {
        running += bounds.get(i);
        suffixLong[i] = running;
    }
    List<Integer> suffix = new ArrayList<>(n);
    for (long v : suffixLong) {
        suffix.add((int) v);
    }
    long totalSum = running;
    return new Pair<>(suffix, totalSum);
}

public static final <V>void reverse(V[] arr,int from,int to){
    if(arr==null||arr.length==0) return;
    int n=arr.length;
    if(from<0) from=0;
    if(to>=n) to=n-1;
    if(from>=to) return;
    while(from<to){
        V tmp=arr[from];
        arr[from]=arr[to];
        arr[to]=tmp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    try {
        while (!list.isEmpty()) {
            // Assuming the list exposes a method to return its first node
            ListNode<E> node = list.getFirst();
            if (node == null) {
                // Defensive check in case getFirst() returned null
                break;
            }
            // Remove the node from the source list
            list.removeListNode(node);
            // Add the node to this list
            this.addListNode(node);
        }
    } catch (RuntimeException e) {
        // Wrap any unexpected runtime exception to give a clear message
        throw new RuntimeException("Failed to atomically move all list nodes", e);
    }
}

