private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    // A subgraph with fewer than two vertices is trivially a clique
    if (vertices.size() < 2) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2) && graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) return bounds;
    for (K key : keys) {
        int bound = 0;
        if (key != null) {
            // If the key is a Number, use its integer value directly.
            if (key instanceof Number) {
                bound = ((Number) key).intValue();
            } else {
                // Otherwise, fall back to the hash code of the key as a simple
                // deterministic numeric representation.
                bound = key.hashCode();
            }
        }
        bounds.add(bound);
    }
    return bounds;
}

private void pop(final String descriptor){
    int count = 0;
    if (descriptor == null || descriptor.length() == 0) return;
    try{
        if (descriptor.charAt(0) == '('){
            int i = 1;
            while (i < descriptor.length() && descriptor.charAt(i) != ')'){
                char c = descriptor.charAt(i);
                if (c == 'L'){
                    int semi = descriptor.indexOf(';', i);
                    if (semi == -1) throw new IllegalArgumentException("Malformed descriptor");
                    i = semi + 1;
                } else if (c == '['){
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') i++;
                    if (i >= descriptor.length()) throw new IllegalArgumentException("Malformed descriptor");
                    i++; // consume element type
                } else {
                    i++; // primitive type
                }
                count++;
            }
        } else {
            if (!descriptor.equals("V")) count = 1;
        }
        if (pos - count < 0) throw new IllegalStateException("Stack underflow");
        pos -= count;
    }catch(RuntimeException e){
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys cannot be null");
    }
    int n = keys.size();
    List<Integer> bounds = new ArrayList<>(n);
    List<Integer> intKeys = new ArrayList<>(n);
    for (K k : keys) {
        if (k == null) {
            intKeys.add(null);
        } else {
            if (!(k instanceof Integer)) {
                throw new IllegalArgumentException("key type must be Integer");
            }
            intKeys.add((Integer) k);
        }
    }
    List<Integer> sorted = new ArrayList<>();
    for (Integer v : intKeys) {
        if (v != null) {
            sorted.add(v);
        }
    }
    Collections.sort(sorted);
    for (Integer key : intKeys) {
        if (key == null) {
            bounds.add(null);
            continue;
        }
        Integer upper;
        int idx = Collections.binarySearch(sorted, key);
        if (idx >= 0) {
            if (idx + 1 < sorted.size()) {
                upper = sorted.get(idx + 1);
            } else {
                upper = Integer.MAX_VALUE;
            }
        } else {
            int insertPos = -idx - 1;
            if (insertPos < sorted.size()) {
                upper = sorted.get(insertPos);
            } else {
                upper = Integer.MAX_VALUE;
            }
        }
        bounds.add(upper);
    }
    return bounds;
}

