public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    // Shortcut: if relative path is empty, return the (normalized) base path
    if (relativePath.isEmpty()) {
        return normalizePath(path);
    }
    // If relativePath starts with '/', treat it as absolute and normalize it directly
    if (relativePath.startsWith("/")) {
        return normalizePath(relativePath);
    }

    // Deque to simulate a stack for path segments
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Determine if the base path is absolute
    boolean baseIsAbsolute = path.startsWith("/");
    // Split the base path into segments
    String[] baseSegments = path.split("/");
    for (String seg : baseSegments) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        if (seg.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(seg);
        }
    }

    // Apply relative path segments
    String[] relSegments = relativePath.split("/");
    for (String seg : relSegments) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        if (seg.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(seg);
        }
    }

    // Build the resulting path string
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    if (baseIsAbsolute) {
        sb.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    // If result is empty, it represents the current directory or root
    return sb.length() == 0 ? (baseIsAbsolute ? "/" : ".") : sb.toString();
}

/**
 * Normalizes a path, resolving "." and ".." segments but keeping the absolute/relative nature.
 */
private static String normalizePath(String p) {
    if (p == null) {
        throw new IllegalArgumentException("path must not be null");
    }
    boolean isAbsolute = p.startsWith("/");
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();
    for (String seg : p.split("/")) {
        if (seg.isEmpty() || seg.equals(".")) {
            continue;
        }
        if (seg.equals("..")) {
            if (!stack.isEmpty() && !stack.peekLast().isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(seg);
        }
    }
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    if (isAbsolute) {
        sb.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    return sb.length() == 0 ? (isAbsolute ? "/" : ".") : sb.toString();
}

static String[] toNoNullStringArray(Object[] array){
    if (array == null) return null;
    boolean hasNull = false;
    for (Object obj : array) {
        if (obj == null) {
            hasNull = true;
            break;
        }
    }
    if (!hasNull) {
        // Safe to return the array cast to String[] if all elements are non-null Strings
        try {
            return (String[]) array;
        } catch (ClassCastException e) {
            // Fallback: create a new String[] copying elements
            String[] result = new String[array.length];
            for (int i = 0; i < array.length; i++) {
                result[i] = (String) array[i];
            }
            return result;
        }
    }
    // Build a new array excluding null elements
    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) nonNullCount++;
    }
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[idx++] = (String) obj;
        }
    }
    return result;
}

