        }
    }
}

public static String toString(final char ch) {
    // Use String.valueOf to convert the char to a String,
    // then intern to ensure the same String instance is returned
    // for the same character value (useful for 7‑bit ASCII characters).
    return String.valueOf(ch).intern();
}

private void checkIfPackedField() throws IOException {
    // Wire type 2 represents a length-delimited field in protobuf.
    // If the current field tag indicates a different wire type, throw an exception.
    if ((tag & 0x07) != 2) {
        throw new IOException("Field is not packed in length-delimited format");
    }
    // Update internal state to indicate that a packed field is being read.
    isPackedField = true;
}

final ByteVector put11(final int byteValue1,final int byteValue2){
    int loc0 = this.length;
    if ( loc0 + 2 > this.data.length ) {
        enlarge(2);
    }
    byte[] loc1 = this.data;
    loc1[loc0++] = (byte) byteValue1;
    loc1[loc0++] = (byte) byteValue2;
    this.length = loc0;
    return this;
}

private String buildContentRange(){
    // Validate start and end positions
    if (startByte < 0 || endByte < 0 || startByte > endByte) {
        // Return null if the range is not properly defined
        return null;
    }
    // Use '*' if total length is unknown
    String totalLengthPart = (contentLength >= 0) ? Long.toString(contentLength) : "*";
    // Construct the Content-Range header value
    return "bytes " + startByte + "-" + endByte + "/" + totalLengthPart;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists()) {
        return result;
    }
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            long timestamp = -1;
            // try to parse a leading long value (e.g., timestamp)
            int commaIdx = line.indexOf(',');
            if (commaIdx != -1) {
                try {
                    timestamp = Long.parseLong(line.substring(0, commaIdx).trim());
                } catch (NumberFormatException e) {
                    // ignore invalid timestamp
                }
            } else {
                // if no comma, try the whole line as a number
                try {
                    timestamp = Long.parseLong(line);
                } catch (NumberFormatException e) {
                    // ignore
                }
            }
            if (timestamp == -1) {
                continue;
            }
            // Filter by time ranges
            boolean inRange = true; // default if no ranges
            if (timeRanges != null && !timeRanges.isEmpty()) {
                inRange = false;
                for (ProfileAnalyzeTimeRange tr : timeRanges) {
                    try {
                        // try contains(long)
                        Method m = tr.getClass().getMethod("contains", long.class);
                        if ((Boolean) m.invoke(tr, timestamp)) {
                            inRange = true;
                            break;
                        }
                    } catch (Exception e) {
                        try {
                            Method getStart = tr.getClass().getMethod("getStart");
                            Method getEnd = tr.getClass().getMethod("getEnd");
                            long start = (Long) getStart.invoke(tr);
                            long end = (Long) getEnd.invoke(tr);
                            if (timestamp >= start && timestamp <= end) {
                                inRange = true;
                                break;
                            }
                        } catch (Exception ignored) { }
                    }
                }
            }
            if (!inRange) {
                continue;
            }
            // create ThreadSnapshot instance via no-arg constructor
            try {
                ThreadSnapshot ts = ThreadSnapshot.class.getDeclaredConstructor().newInstance();
                try {
                    Method setTs = ThreadSnapshot.class.getMethod("setTimestamp", long.class);
                    setTs.invoke(ts, timestamp);
                } catch (NoSuchMethodException nsme) {
                    try {
                        Field tsField = ThreadSnapshot.class.getDeclaredField("timestamp");
                        tsField.setAccessible(true);
                        tsField.setLong(ts, timestamp);
                    } catch (Exception ignored) { }
                }
                result.add(ts);
            } catch (Exception e) {
                // if we cannot instantiate, skip this entry
            }
        }
    }
    return result;
}
